def verify(witness):
    # exact integer arithmetic only; fail closed via exception
    if witness['n'] != 4:
        raise AssertionError('n must be 4')
    pts = witness['points']
    if len(pts) != 4:
        raise AssertionError('expected 4 points')
    for p in pts:
        if len(p) != 2:
            raise AssertionError('point arity')
        for c in p:
            if not isinstance(c, int) or isinstance(c, bool):
                raise AssertionError('coordinates must be exact integers')
    # distinctness of points
    for i in range(4):
        for j in range(i + 1, 4):
            if pts[i][0] == pts[j][0] and pts[i][1] == pts[j][1]:
                raise AssertionError('repeated point')
    # exact squared distances
    sq = [[0, 0, 0, 0] for _ in range(4)]
    for i in range(4):
        for j in range(4):
            if i == j:
                continue
            dx = pts[i][0] - pts[j][0]
            dy = pts[i][1] - pts[j][1]
            d = dx * dx + dy * dy
            if d <= 0:
                raise AssertionError('nonpositive squared distance')
            sq[i][j] = d
    # per-point count of distinct squared distances (exact)
    counts = []
    for i in range(4):
        s = set()
        for j in range(4):
            if j != i:
                s.add(sq[i][j])
        counts.append(len(s))
    for c in counts:
        if c < 1 or c > 3:
            raise AssertionError('count outside [1,3]')
    vals = set(counts)
    if len(vals) != 3:
        raise AssertionError('not 3 distinct R-values')
    if vals != {1, 2, 3}:
        raise AssertionError('wrong value set')
    return True

WITNESS = {'n': 4, 'points': [[0, 0], [1, 0], [0, 1], [-1, 0]]}
RESULT = verify(WITNESS)
assert RESULT is True
